def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return float("inf"), None

    # Priority queue to store (dist, current_node, prev_node) pairs
    distances = {node: float("inf") for node in graph} # initial distances set to infinity except source's distance is 0
