def shortest_path(graph, source, target):
    # Initialize the unvisited nodes and distances, and previous nodes dictionary
    unvisited = list(graph.keys())
    distances = {node: float("inf") for node in graph.keys()}
    distances[source] = 0
    previous_nodes = {node: None for node in graph.keys()}

    # Dijkstra's algorithm implementation
    while unvisited:
        # Relax all the neighbors of current node / vertice
        for neighbor in graph.get(unvisited[0], []):
            cost = distances[unvisited[0]] + neighbor[1]
            if cost < distances[neighbor[0]]:
                distances[neighbor[0]] = cost
                previous_nodes[neighbor[0]] = unvisited[0]

        # Mark the current node / vertice as visited and remove it from the unvisited list
        if unvisited[0] in graph:
            del graph[unvisited[0]]

        # Move the current node / vertice in the next state so we will check it after the rest neigbhors.
        if len(unvisited) > 1:
            unvisited.append(unvisited.pop(0))
        else:
            unvisited.pop(0)

    # Edge case: check whether target is in visited nodes afterwards
    if distances[target] == float("inf"):
        return float("inf"), None
    else:
        path = []
        node = target
        while node:
            path.append(node)
            node = previous_nodes.get(node, None)
        path.reverse()
        return (distances[target], path)

