from math import inf

def shortest_path(graph, source, target):
    # Priority queue setup with the distance and the node
    priorities = [(0, source)]
    # A set to store the nodes we've visit
    visited = set()
    # A dictionary to keep track of the previous node in the shortest path
    prev = {}
    # In case we should throw not reach the target, return infinite
    distance = {node: inf for node in graph}
    distance[source] = 0

    while priorities:
        current_dist, node = heappop(priorities)
        visited.add(node)

        if node == target:
            path = []
            while node:
                path.append(node)
                node = prev.get(node)
            return (distance[target], path[::-1])

        if current_dist > distance[node]:
            continue

        for neighbour, weight in graph.get(node, []):
            if neighbour in visited:
                continue
            new_dist = current_dist + weight

            if new_dist < distance[neighbour]:
                distance[neighbour] = new_dist
                prev[neighbour] = node
                heappush(priorities, (new_dist, neighbour))

    return (float("inf"), None)

