    edges = {}
    for node, edges_from_this in graph.items():
        for neighbor, weight in edges_from_this:
            edges.setdefault(neighbor, []).append((node, weight))

    # Initialize the distance list with infinity values for all nodes except source (which places we can project)
    distance = {node: float("inf") for node in graph}
    distance[source] = 0
    #Initialize the visited set, earlier add the source node, we'll process them one by one 
    visited = {source}
    # Queue to store thelist concentations(path) and distance (cost)
    breadth_first_queue = deque([(0, source)])

    # Process tomentation Algorithm to finishing examine paths, order of exploring nodes
    while breadth_first_queue:
        current_distance, current_node = breadth_first_queue.popleft()

        # To shorten node value within visited visit
        for neighbor in edges.get(current_node, []):
            if neighbor[0] in visited:
