        path = []
        current_node = target
        while current_node is not None:
            path.append(current_node)
            current_node = predecessors[current_node]

        if not path:
            return float('inf'), []    
        path = path[::-1]  
        return (shortest_distances[target], path)

    return single_source_dijkstra(graph, source, target)

