import heapq

def shortest_path(graph, source, target):
    def calculate_distance(graph):
        distances = {node: float("inf") for node in graph}
        distances[source] = 0
        priority_queue = [(0, source)]

        while priority_queue:
            dist, node = heapq.heappop(priority_queue)

            if dist > distances[node]:
                continue

            for neighbor, weight in graph[node]:
                distance = dist + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return distances

    def trace_path(graph, target, distance):
        path = []
        while target is not None:
            path.append(target)
            if distance == float("inf"):
                return path
            for node in graph[target]:
                if graph[node[0]][0] == target and node[1] == distance - distances[target]:
                    target = node[0]
                    break                
            else:
                target = source
        path.append(source)
        path.reverse()
        return path

    distances = calculate_distance(graph)
    if distances[target] == float("inf"):
        return float("inf"), None
    return distances[target], trace_path(graph, target, distances[target])

