from collections import deque

def shortest_path(graph, source, target):
    # Initialize variables.
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    queue = deque([source])
    
    # Min heap. Practically, we use Queue as a very fast mim heap implementation
    # would be complex/difficult to implement
    # with TC O(log(v)),sparse underlying data structure fetching needed O(1)
    previous = {node: None for node in graph}
    processed = set()
    
    def relax(u, v, weight):
        nonlocal previous, distances
        if distances[v] > distances[u] + weight:
            distances[v] = distances[u] + weight
            previous[v] = u
            if v not in processed:
                queue.append(v)
    
    while queue:
        u = queue.popleft()
        processed.add(u)
        for i, (v, weight) in enumerate(graph[u]):
            relax(u, v, weight)
            if v == target:  # If the target is visited, we can return the result early
                path = []
                while v:
                    path.append(v)
                    v = previous[v]
                return (distances[target], list(reversed(path)))
        for node in graph:
            if node not in processed and node not in queue:
                queue.append(node)
               
    return (float('inf'), None)  # If the code has vanished back here-> unreachable
    
# Example usage
